<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Print Basic List</h1><p>Persisted student directory and outstanding fees.</p></div><button class="btn btn--primary" type="button" onclick="window.print()">Print</button></header><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label>Search</label><input class="module-input" name="search" value="<?= e($search) ?>"></div><div class="module-field"><label>Class</label><select class="module-select" name="class"><option value="">All Classes</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $selectedClass==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--secondary">Filter</button></form><section class="module-card"><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>SR</th><th>REG #</th><th>Student Name</th><th>Father Name</th><th>Class</th><th>Fee Remaining</th><th>Phone</th></tr></thead><tbody><?php foreach($students as$i=>$s):?><tr><td><?= $paginator->offset()+$i+1 ?></td><td><?= e($s['registration_no']) ?></td><td><?= e($s['student_name']) ?></td><td><?= e($s['father_name']?:'—') ?></td><td><?= e($s['class_name']) ?></td><td><?= number_format((float)$s['fee_remaining'],2) ?></td><td><?= e($s['mobile']?:$s['father_mobile']?:'—') ?></td></tr><?php endforeach ?><?php if(!$students):?><tr><td colspan="7">No records found.</td></tr><?php endif ?></tbody></table></div><p>Page <?= $paginator->currentPage ?> of <?= $paginator->lastPage() ?> · <?= $paginator->total ?> records</p><div class="filter-actions"><?php if($paginator->hasPrevious()):?><a class="btn btn--secondary" href="?search=<?= urlencode($search) ?>&class=<?= $selectedClass ?>&page=<?= $paginator->currentPage-1 ?>">Previous</a><?php endif ?><?php if($paginator->hasNext()):?><a class="btn btn--secondary" href="?search=<?= urlencode($search) ?>&class=<?= $selectedClass ?>&page=<?= $paginator->currentPage+1 ?>">Next</a><?php endif ?></div></div></section></div></div></main>
